import React from 'react';
import "./box.css"
function Box() {
  return (
    <div className="box">
      <h1>Name:Shanmukhi Priya</h1>
      <p>Roll No : 210</p>
      <input type="email" placeholder="Enter Email" />
      <button>Submit</button>
    </div>
  );
}
export default Box;
